"""Registertabelle -- alle Register der Modbus-Doku B1200522 als Daten.

GENERIERT von scripts/tabelle_erzeugen.py. Nicht von Hand aendern:
Aenderungen gehoeren in den Generator, in documentation/registerliste_b1200522.json
oder in scripts/bestand_0_4.json.

Eine Zeile je Register. Die 177 Entitaeten der Fassung 0.4.0 tragen in
``alter_schluessel``, ``altes_geraet`` und ``alte_gruppe`` ihre bisherigen
Kennungen, damit unique_id, entity_id und Geraet erhalten bleiben. Einheit,
Faktor, Dezimalen und Grenzen folgen fuer diese Zeilen dem bisherigen Code,
sonst der Doku.

Kategorien: ``istwert`` (Input-Register, Coils, Discrete Inputs), ``betrieb``
(Parameter der Kundenebene), ``service`` (uebrige Parameter, keine Entitaet),
``fernsteuerung`` (48001-48046, siehe Befund) und ``undokumentiert`` (antwortet,
Bedeutung unbekannt, nie Entitaet).
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class Register:
    nummer: int
    typ: str                 # "input" | "holding" | "coil" | "discrete"
    familie: str             # "kessel", "hk", "boiler", "puffer", "austragung", ...
    instanz: int | None
    schluessel: str          # ohne Instanz, z. B. "frostschutztemperatur"
    name_de: str             # Doku-Beschreibung ohne Instanzpraefix
    einheit: str
    faktor: int
    dezimalen: int
    minimum: int | None
    maximum: int | None
    rw: str                  # "R" | "R/W"
    kategorie: str           # "istwert" | "betrieb" | "service" | "fernsteuerung" | "undokumentiert"
    plattform: str | None    # "sensor" | "binary_sensor" | "number" | "switch" | "select" | "time" | None
    geraeteklasse: str | None
    werteliste: str | None
    zustandsklasse: str | None   # "total_increasing" fuer Zaehler, sonst None (= measurement)
    freigegeben: bool            # wird gelesen und (wenn plattform gesetzt) eine Entitaet
    gruppe: str | None           # Haken im Config-Entry; None = immer (Regler)
    alter_schluessel: str | None
    altes_geraet: str | None
    alte_gruppe: str | None

    @property
    def entitaetsschluessel(self) -> str:
        """Interner Schluessel: alter fuer den Bestand, sonst Gruppe + Schluessel."""
        return self.alter_schluessel or f"{self.gruppe or 'controller'}_{self.schluessel}"

    @property
    def instanzkennung(self) -> str:
        """hk02, boiler01, puffer01 -- sonst die Familie."""
        if self.instanz is None:
            return self.familie
        return f"{self.familie}{self.instanz:02d}"

    @property
    def adresse(self) -> int:
        """Nullbasierte Modbus-Adresse fuer den Function-Code."""
        return {"input": self.nummer - 30001, "holding": self.nummer - 40001,
                "discrete": self.nummer - 10001, "coil": self.nummer}[self.typ]


