NACH_NUMMER: dict[tuple[str, int], Register] = {(r.typ, r.nummer): r for r in TABELLE}
NACH_ALTEM_SCHLUESSEL: dict[str, Register] = {r.alter_schluessel: r for r in TABELLE if r.alter_schluessel}


def fuer_instanz(kennung: str) -> tuple[Register, ...]:
    """Alle Zeilen einer Instanz (hk02, boiler01, kessel, ...)."""
    return tuple(r for r in TABELLE if r.instanzkennung == kennung)
